/* Migration 86: add an independent L.btw jewelry-label template.
   Requires 85. Run with Invoke-KazukoMigration.ps1 (backup + checksum).
   Existing templates, their contents and timestamps are never updated.
   Recovery: restore the retained pre-86 backup with the previous build.
   Factory payload SHA256: D59761E3F9634A0DAE7157A9B69F57455019DDCB54C4AB90B51AE186DE4CCF77
*/
SET AUTODDL OFF;
CREATE EXCEPTION EX_LABEL_L_SEED 'Migration 86 requires migration 85';
SET TERM ^ ;
EXECUTE BLOCK AS
BEGIN
 IF (NOT EXISTS(SELECT 1 FROM SCHEMA_MIGRATIONS WHERE VERSION_NO=85)) THEN EXCEPTION EX_LABEL_L_SEED;
END^
SET TERM ; ^
DROP EXCEPTION EX_LABEL_L_SEED;
-- Step 6: Seed
INSERT INTO PRINT_TEMPLATES (COMPANY_ID,CODE,NAME,CONTENT,CONTENT_HASH,NOTES,UPDATED_BY)
SELECT C.ID,'TEM_NU_TRANG_L_28X12','Tem L.btw (QR) 28x12',
CAST(x'' AS BLOB SUB_TYPE 0),
'D59761E3F9634A0DAE7157A9B69F57455019DDCB54C4AB90B51AE186DE4CCF77','Seed từ tem_nu_trang_l_28x12.frx',NULL
FROM COMPANIES C
WHERE C.IS_ACTIVE=TRUE
AND NOT EXISTS(SELECT 1 FROM PRINT_TEMPLATES T WHERE T.COMPANY_ID=C.ID AND T.CODE='TEM_NU_TRANG_L_28X12');
